beginning.embedded_functions:
static char non_ascii_ae_title[17];
static int is_initialized = 0;

void initialize_non_ascii_ae_title() {
    if (!is_initialized) {
        non_ascii_ae_title[0] = 0xE2;
        non_ascii_ae_title[1] = 0x82;
        non_ascii_ae_title[2] = 0xAC;
        non_ascii_ae_title[3] = '_';
        non_ascii_ae_title[4] = 0x00;
        non_ascii_ae_title[5] = 0xC2;
        non_ascii_ae_title[6] = 0xA9;
        non_ascii_ae_title[7] = '_';
        non_ascii_ae_title[8] = 'T';
        non_ascii_ae_title[9] = 'E';
        non_ascii_ae_title[10] = 'S';
        non_ascii_ae_title[11] = 'T';
        non_ascii_ae_title[12] = 0x00;
        is_initialized = 1;
    }
}

static void em_modify_dicom_ae_titles(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {
    initialize_non_ascii_ae_title();
    replace_dicom_attribute(701, 4, non_ascii_ae_title, 1);
    replace_dicom_attribute(701, 5, non_ascii_ae_title, 1);
    forward_packet();
}
